SELECT date_trunc('month', order_date) AS m, SUM(amount) FROM orders GROUP BY 1;
-- calendar spine via generate_series
WITH RECURSIVE days AS (
  SELECT generate_series(DATE '2024-01-01', DATE '2024-12-31', INTERVAL '1 day')::date AS day
)
SELECT * FROM days;

blocks.mysql:
-- MySQL 8.0: DATE_FORMAT makes text buckets
SELECT DATE_FORMAT(order_date, '%Y-%m-01') AS m, SUM(amount) FROM orders GROUP BY 1;
-- calendar spine via recursive CTE
WITH RECURSIVE days AS (
  SELECT DATE '2024-01-01' AS day
  UNION ALL
  SELECT day + INTERVAL 1 DAY FROM days WHERE day < DATE '2024-12-31'
)
SELECT day FROM days;

